import React, { useState, useEffect } from 'react';
import { 
  Users, Copy, Check, LogOut, LayoutDashboard, ShieldCheck, Award, GraduationCap, Calendar, Phone, Share2
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { commercialAPI, authAPI } from '../services/api';
import { clearSession } from '../utils/authSession';
import FloatingAIAssistant from './FloatingAIAssistant';
import AnimatedBackground from './AnimatedBackground';
import AnimatedCounter from './AnimatedCounter';
import BrandedLoader from './BrandedLoader';
import ProfileModal from './ProfileModal';
import AssistanceWidget from './AssistanceWidget';
import MobileMenu from './MobileMenu';
import LogoutConfirmModal from './LogoutConfirmModal';
import { pushBackHandler } from '../utils/backHandler';
import useIsMobile from '../hooks/useIsMobile';
import '../Dashboard.css';

const CommercialDashboard = () => {
  const [stats, setStats] = useState(null);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    const off = pushBackHandler(() => {
      if (showLogoutConfirm) { setShowLogoutConfirm(false); return true; }
      if (showProfile) { setShowProfile(false); return true; }
      return false;
    });
    return off;
  }, [showLogoutConfirm, showProfile]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const uRes = await authAPI.getProfile();
      setUser(uRes.data);
      const sRes = await commercialAPI.getStats();
      setStats(sRes.data);
    } catch (err) {
      console.error("Erreur de chargement des données commercial", err);
    } finally {
      setLoading(false);
    }
  };

  // Code de parrainage avec valeur de secours (stats OU profil utilisateur)
  const codeParrain = stats?.codeCommercial || user?.codeCommercial || '';

  const copyToClipboard = () => {
    if (codeParrain) {
      navigator.clipboard.writeText(codeParrain);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  // Partage direct du code aux étudiants (WhatsApp / partage natif du téléphone)
  const shareCode = async () => {
    if (!codeParrain) return;
    const message =
      `🎓 Rejoins RevisIA_H24 !\n\n` +
      `Inscris-toi avec mon code parrain : ${codeParrain}\n\n` +
      `Tu auras accès aux cours, annales, corrigés types et à l'assistant IA. À très vite ! 🚀`;
    if (navigator.share) {
      try { await navigator.share({ title: 'RevisIA_H24 — Code parrain', text: message }); } catch (e) { /* annulé */ }
    } else {
      window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
    }
  };

  const isMobile = useIsMobile();

  if (loading) {
    return <BrandedLoader message="Chargement de l'espace commercial…" variant="blue" />;
  }

  return (
    <div className="elite-dashboard" style={{ background: '#090D1A', color: '#E2E8F0', minHeight: '100vh', fontFamily: 'Inter, sans-serif' }}>
      <AnimatedBackground variant="blue" intensity={0.4} />
      {/* Barre latérale premium */}
      <MobileMenu />
      <aside className="elite-sidebar" style={{ background: 'rgba(11, 17, 34, 0.9)', borderRight: '1px solid #f1f5f9' }}>
        <div className="brand-elite">
          <ShieldCheck color="#38BDF8" size={28} style={{ filter: 'drop-shadow(0 0 10px #38BDF866)' }} />
          <span style={{ fontWeight: '800', letterSpacing: '1.5px', color: 'white' }}>RevisIA_H24 <small style={{ color: '#38BDF8', fontSize: '0.65em', display: 'block', fontWeight: 'bold' }}>COMMERCIAL</small></span>
        </div>
        <nav className="elite-nav" style={{ marginTop: '2rem' }}>
          <button className="active" style={{ background: 'rgba(56, 189, 248, 0.1)', color: '#38BDF8', borderLeft: '3px solid #38BDF8' }}>
            <LayoutDashboard size={20} /> Vue d'ensemble
          </button>
        </nav>
        <div className="sidebar-footer" style={{ borderTop: '1px solid #f1f5f9' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '1.5rem', padding: '0 0.5rem' }}>
            <div onClick={() => setShowProfile(true)} style={{ cursor: 'pointer', width: '40px', height: '40px',
              borderRadius: '50%', background: 'linear-gradient(135deg, #1D4ED8, #F97316)',
              display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white',
              fontWeight: 'bold', fontSize: '1.1rem', overflow: 'hidden', flexShrink: 0 }}>
              {user?.photoUrl
                ? <img src={user.photoUrl} alt="avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                : (user?.nomComplet ? user.nomComplet.charAt(0).toUpperCase() : 'C')
              }
            </div>
            <div onClick={() => setShowProfile(true)} style={{ cursor: 'pointer' }}>
              <p style={{ margin: 0, fontSize: '0.9rem', fontWeight: 'bold', color: 'white' }}>{user?.nomComplet}</p>
              <p style={{ margin: 0, fontSize: '0.75rem', color: '#475569' }}>Commercial Agréé</p>
            </div>
          </div>
          <button className="btn-logout" onClick={() => setShowLogoutConfirm(true)}>
            <LogOut size={16} /> Se déconnecter
          </button>
        </div>
      </aside>

      {/* Zone de contenu principal */}
      <main className="elite-main" style={{ position: 'relative', zIndex: 1 }}>
        <header className="elite-header" style={{ marginBottom: '2rem' }}>
          <div>
            <h1 style={{ fontSize: '2rem', fontWeight: '800', color: 'white' }}>
              Dashboard <span className="text-glow" style={{ color: '#F97316', backgroundImage: 'linear-gradient(135deg, #3B82F6, #F97316)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Commercial</span>
            </h1>
            <p style={{ color: '#475569', marginTop: '0.3rem' }}>Gérez vos parrainages et suivez votre impact sur l'inscription des étudiants.</p>
          </div>
        </header>

        {/* Section haute : Carte de parrainage et indicateurs */}
        <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(auto-fit, minmax(300px, 1fr))', gap: isMobile ? '1rem' : '1.5rem', marginBottom: isMobile ? '1.5rem' : '2.5rem' }}>
          {/* Carte Code Unique */}
          <div className="elite-card hover-lift anim-fade-up" style={{ padding: '2rem', background: 'linear-gradient(135deg, rgba(30, 41, 59, 0.7), rgba(15, 23, 42, 0.8))', border: '1px solid rgba(56, 189, 248, 0.15)', borderRadius: '24px', position: 'relative', overflow: 'hidden', boxShadow: '0 20px 40px rgba(0,0,0,0.3)' }}>
            <div style={{ position: 'absolute', top: '-40px', right: '-40px', width: '150px', height: '150px', background: 'radial-gradient(circle, rgba(56,189,248,0.15) 0%, rgba(0,0,0,0) 70%)', borderRadius: '50%' }} />
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '1.5rem' }}>
              <div style={{ padding: '10px', background: 'rgba(56, 189, 248, 0.1)', borderRadius: '12px', color: '#38BDF8' }}><Award size={24} /></div>
              <h3 style={{ fontSize: '1.1rem', fontWeight: '700', color: 'white', margin: 0 }}>Votre Code Parrainage</h3>
            </div>
            
            <p style={{ color: '#475569', fontSize: '0.85rem', marginBottom: '1rem', lineHeight: '1.5' }}>
              Envoyez ce code aux étudiants. Chaque étudiant qui s'inscrit avec votre code est rattaché à votre compte, et vous touchez une commission. 💰
            </p>

            {/* Le CODE en grand, bien visible */}
            <div style={{
              textAlign: 'center',
              background: 'linear-gradient(135deg, rgba(56,189,248,0.12), rgba(249,115,22,0.10))',
              padding: '20px', borderRadius: '18px',
              border: '2px dashed rgba(56,189,248,0.45)', marginBottom: '14px'
            }}>
              <span style={{
                fontSize: '2.1rem', fontWeight: '900', color: 'white',
                letterSpacing: '4px', fontFamily: 'monospace',
                textShadow: '0 0 20px rgba(56,189,248,0.5)'
              }}>
                {codeParrain || 'Génération…'}
              </span>
            </div>

            {/* Boutons Copier + Partager */}
            <div style={{ display: 'flex', gap: '10px' }}>
              <button
                onClick={copyToClipboard}
                disabled={!codeParrain}
                style={{ flex: 1, background: copied ? 'rgba(16, 185, 129, 0.15)' : 'rgba(56, 189, 248, 0.15)', color: copied ? '#10B981' : '#38BDF8', border: 'none', borderRadius: '12px', padding: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', fontSize: '0.9rem', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.3s ease' }}
              >
                {copied ? <Check size={18} /> : <Copy size={18} />}
                {copied ? 'Copié !' : 'Copier'}
              </button>
              <button
                onClick={shareCode}
                disabled={!codeParrain}
                style={{ flex: 1.4, background: 'linear-gradient(135deg, #25D366, #128C7E)', color: 'white', border: 'none', borderRadius: '12px', padding: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', fontSize: '0.9rem', fontWeight: 'bold', cursor: 'pointer', boxShadow: '0 8px 20px rgba(37,211,102,0.3)' }}
              >
                <Share2 size={18} /> Partager aux étudiants
              </button>
            </div>
          </div>

          {/* Indicateur : Total étudiants */}
          <div className="elite-card hover-lift anim-fade-up" style={{ padding: '2rem', background: 'rgba(15, 23, 42, 0.5)', border: '1px solid #f8fafc', borderRadius: '24px', display: 'flex', alignItems: 'center', gap: '1.5rem', boxShadow: '0 10px 30px rgba(0,0,0,0.15)' }}>
            <div style={{ width: '65px', height: '65px', borderRadius: '20px', background: 'rgba(59, 130, 246, 0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#3B82F6' }}>
              <Users size={32} />
            </div>
            <div>
              <h3 style={{ fontSize: '2.5rem', fontWeight: '800', color: 'white', margin: 0 }}>
                <AnimatedCounter value={stats?.totalInscrits || 0} duration={1100} />
              </h3>
              <p style={{ color: '#475569', margin: 0, fontSize: '0.9rem', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Étudiants Inscrits</p>
            </div>
          </div>

          {/* Indicateur : Commissions (10%) */}
          <div className="elite-card hover-lift anim-fade-up" style={{ padding: '2rem', background: 'rgba(15, 23, 42, 0.5)', border: '1px solid rgba(16, 185, 129, 0.15)', borderRadius: '24px', display: 'flex', alignItems: 'center', gap: '1.5rem', boxShadow: '0 10px 30px rgba(0,0,0,0.15)' }}>
            <div style={{ width: '65px', height: '65px', borderRadius: '20px', background: 'rgba(16, 185, 129, 0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#10B981' }}>
              <span style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>FCFA</span>
            </div>
            <div>
              <h3 style={{ fontSize: '2.2rem', fontWeight: '800', color: '#10B981', margin: 0 }}>
                <AnimatedCounter value={stats?.commissionEstimee || 0} duration={1400} />
              </h3>
              <p style={{ color: '#475569', margin: 0, fontSize: '0.9rem', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                Commissions ({stats?.tauxCommission != null ? stats.tauxCommission : 10}%)
              </p>
            </div>
          </div>
        </div>

        {/* Tableau moderne des inscriptions */}
        <h2 style={{ fontSize: isMobile ? '1.1rem' : '1.4rem', fontWeight: '800', color: 'white', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <GraduationCap size={22} color="#38BDF8" /> Étudiants inscrits via votre code
        </h2>
        
        <div className="elite-card hover-lift anim-fade-up" style={{ padding: '0', background: 'rgba(11, 17, 34, 0.5)', border: '1px solid #f8fafc', borderRadius: '24px', overflow: 'hidden', boxShadow: '0 20px 40px rgba(0,0,0,0.2)' }}>
          {stats?.etudiants && stats.etudiants.length > 0 ? (
            <div style={{ overflowX: 'auto' }}>
              <table className="table-elite" style={{ width: '100%', textAlign: 'left', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
                <thead>
                  <tr style={{ background: 'rgba(15, 23, 42, 0.8)', borderBottom: '1px solid #f1f5f9', color: '#475569' }}>
                    <th style={{ padding: '1.2rem' }}>Nom de l'étudiant</th>
                    <th style={{ padding: '1.2rem' }}>Téléphone</th>
                    <th style={{ padding: '1.2rem' }}>Filière / École</th>
                    <th style={{ padding: '1.2rem' }}>Niveau</th>
                    <th style={{ padding: '1.2rem' }}>Dépenses</th>
                    <th style={{ padding: '1.2rem' }}><Calendar size={16} style={{ display: 'inline', marginRight: '4px', verticalAlign: 'text-bottom' }} /> Date d'inscription</th>
                  </tr>
                </thead>
                <tbody>
                  {stats.etudiants.map((etud, idx) => (
                    <tr key={idx} style={{ borderBottom: '1px solid #f8fafc', transition: 'background 0.2s', cursor: 'default' }} onMouseEnter={(e) => e.currentTarget.style.backgroundColor = 'rgba(255,255,255,0.01)'} onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}>
                      <td style={{ padding: '1.2rem', color: 'white', fontWeight: '600' }}>{etud.nomComplet}</td>
                      <td style={{ padding: '1.2rem', color: '#475569' }}>
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: 'rgba(0,0,0,0.2)', padding: '4px 10px', borderRadius: '8px', border: '1px solid #f8fafc', fontSize: '0.85rem' }}>
                          <Phone size={12} color="#64748B" /> {etud.numeroTelephone}
                        </span>
                      </td>
                      <td style={{ padding: '1.2rem', color: '#38BDF8', fontWeight: '500' }}>{etud.filiere}</td>
                      <td style={{ padding: '1.2rem' }}>
                        <span style={{ display: 'inline-block', padding: '4px 10px', background: 'rgba(249, 115, 22, 0.1)', color: '#F97316', borderRadius: '6px', fontSize: '0.8rem', fontWeight: 'bold', border: '1px solid rgba(249,115,22,0.2)' }}>
                          {etud.niveau}
                        </span>
                      </td>
                      <td style={{ padding: '1.2rem', color: '#10B981', fontWeight: 'bold' }}>
                        {etud.totalDepense ? etud.totalDepense.toLocaleString('fr-FR') + ' FCFA' : '0 FCFA'}
                      </td>
                      <td style={{ padding: '1.2rem', color: '#475569' }}>
                        {etud.dateInscription ? new Date(etud.dateInscription).toLocaleString('fr-FR', { dateStyle: 'medium', timeStyle: 'short' }) : 'Non précisée'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div style={{ padding: '4rem 2rem', textAlign: 'center', color: '#475569' }}>
              <div style={{ display: 'inline-flex', padding: '1.5rem', background: '#f8fafc', borderRadius: '50%', marginBottom: '1rem' }}><Users size={32} /></div>
              <p style={{ fontSize: '1.1rem', fontWeight: '600', color: '#475569', marginBottom: '0.5rem' }}>Aucun parrainage enregistré</p>
              <p style={{ fontSize: '0.85rem', maxWidth: '380px', margin: '0 auto' }}>
                Partagez votre code commercial pour commencer à inscrire des étudiants et suivre vos performances en temps réel.
              </p>
            </div>
          )}
        </div>
      </main>
      <FloatingAIAssistant user={user} />
      <AnimatePresence>
        {showProfile && user && (
          <ProfileModal user={user} onClose={() => setShowProfile(false)}
            onSaved={(u) => setUser(p => ({ ...p, ...u }))} />
        )}
      </AnimatePresence>
      <AssistanceWidget universiteId={user?.universite?.id} />
      <LogoutConfirmModal isOpen={showLogoutConfirm} onClose={() => setShowLogoutConfirm(false)} />
    </div>
  );
};

export default CommercialDashboard;

